def is_valid_date(id_card):
    try:
        year, month, day = [int(x) for x in id_card.split('-')]
        if month < 1 or month > 12:
            return None
        if day < 1 or day > 31:
            return None
        return f'{year}-{month:02}-{day:02}'
    except ValueError:
        return None

