def is_same_letter_combination(word1, word2):
    """
    :param word1: 第一个单词
    :param word2: 第二个单词
    :return: True if the two words are the same, False otherwise
    """
    # 将单词转换为字符串
    word1 = ''.join(sorted(word1))
    word2 = ''.join(sorted(word2))

    # 将单词转换为字典
    word1_dict = {}
    for char in word1:
        word1_dict[char] = 1

    word2_dict = {}
    for char in word2:
        word2_dict[char] = 1

    # 遍历字典
    for char in word1:
        if char not in word2_dict:
            return False
        word2_dict[char] -= 1

    # 遍历字典
    for char in word2:
        if char not in word1_dict:
            return False
        word1_dict[char] -= 1

    return True


